import{_ as n,c as i,o as r,ag as a}from"./chunks/framework.DfL_BkQ-.js";const g=JSON.parse('{"title":"Einführung","description":"","frontmatter":{},"headers":[],"relativePath":"de/guide/introduction.md","filePath":"de/guide/introduction.md","lastUpdated":1794112334000}'),t={name:"de/guide/introduction.md"};function s(h,e,d,l,o,u){return r(),i("div",null,[...e[0]||(e[0]=[a('<h1 id="einfuhrung" tabindex="-1">Einführung <a class="header-anchor" href="#einfuhrung" aria-label="Permalink to &quot;Einführung&quot;">​</a></h1><h2 id="uber-nicasa" tabindex="-1">Über Nicasa <a class="header-anchor" href="#uber-nicasa" aria-label="Permalink to &quot;Über Nicasa&quot;">​</a></h2><p>Nicasa ist ein moderner Desktop-Bildbetrachter und ein Screenshot-Tool, das auf Geschwindigkeit, Einfachheit und leistungsstarke Bearbeitung ausgelegt ist. Nicasa wurde exklusiv für macOS entwickelt und bringt ein flüssiges, modernes Bilderlebnis auf deinen Schreibtisch.</p><h2 id="hauptfunktionen" tabindex="-1">Hauptfunktionen <a class="header-anchor" href="#hauptfunktionen" aria-label="Permalink to &quot;Hauptfunktionen&quot;">​</a></h2><h3 id="🖼️-bilder-besser-ansehen" tabindex="-1">🖼️ <strong>Bilder besser ansehen</strong> <a class="header-anchor" href="#🖼️-bilder-besser-ansehen" aria-label="Permalink to &quot;🖼️ **Bilder besser ansehen**&quot;">​</a></h3><p>Öffne Bilder sofort mit einer klaren, fokussierten Oberfläche. Keine Ablenkung, kein Durcheinander – nur dein Inhalt, schön präsentiert in dem Moment, in dem du ihn öffnest.</p><h3 id="📸-screenshots-und-aufnahmen" tabindex="-1">📸 <strong>Screenshots und Aufnahmen</strong> <a class="header-anchor" href="#📸-screenshots-und-aufnahmen" aria-label="Permalink to &quot;📸 **Screenshots und Aufnahmen**&quot;">​</a></h3><p>Erfasse jeden Teil deines Bildschirms in Sekunden. Mit schnellen, präzisen Screenshot-Werkzeugen direkt in Nicasa war das Speichern und Teilen visueller Ideen nie einfacher.</p><h3 id="🤖-ki-bildeditor" tabindex="-1">🤖 <strong>KI-Bildeditor</strong> <a class="header-anchor" href="#🤖-ki-bildeditor" aria-label="Permalink to &quot;🤖 **KI-Bildeditor**&quot;">​</a></h3><p>Verbessere und verfeinere deine Bilder mit leistungsstarken KI-Werkzeugen. Von schnellen Anpassungen bis zu intelligenter Bearbeitung hilft dir Nicasa, Bilder mühelos zu verwandeln.</p><h3 id="🔍-transparenter-overlay-modus" tabindex="-1">🔍 <strong>Transparenter Overlay-Modus</strong> <a class="header-anchor" href="#🔍-transparenter-overlay-modus" aria-label="Permalink to &quot;🔍 **Transparenter Overlay-Modus**&quot;">​</a></h3><p>Ein leistungsstarkes Werkzeug für Designer und Künstler: Hefte ein Bild mit einstellbarer Transparenz über alle Fenster – ideal zum Nachzeichnen, für Referenzarbeit und UI-Vergleiche.</p><h3 id="🌐-integration-der-chrome-erweiterung" tabindex="-1">🌐 <strong>Integration der Chrome-Erweiterung</strong> <a class="header-anchor" href="#🌐-integration-der-chrome-erweiterung" aria-label="Permalink to &quot;🌐 **Integration der Chrome-Erweiterung**&quot;">​</a></h3><p>Verbinde dich nahtlos mit der Nicasa Chrome-Erweiterung, um alle Bilder jeder Webseite an einem Ort zu sehen. Extrahiere, durchstöbere und öffne Bilder direkt in Nicasa für ein schnelleres und intensiveres Erlebnis.</p><h3 id="🎨-flussiges-und-intuitives-design" tabindex="-1">🎨 <strong>Flüssiges und intuitives Design</strong> <a class="header-anchor" href="#🎨-flussiges-und-intuitives-design" aria-label="Permalink to &quot;🎨 **Flüssiges und intuitives Design**&quot;">​</a></h3><p>Angetrieben von Technologie der nächsten Generation liefert Nicasa fließende Übergänge, gestochen scharfe Darstellung und durchdachtes Interaktionsdesign.</p><h2 id="systemanforderungen" tabindex="-1">Systemanforderungen <a class="header-anchor" href="#systemanforderungen" aria-label="Permalink to &quot;Systemanforderungen&quot;">​</a></h2><ul><li><strong>Betriebssystem</strong>: macOS 10.13 oder neuer</li><li><strong>Arbeitsspeicher</strong>: mindestens 4 GB RAM, 8 GB empfohlen</li><li><strong>Speicherplatz</strong>: 54,5 MB für die Installation</li><li><strong>Display</strong>: mindestens 1280x720 Auflösung</li></ul><h2 id="unterstutzte-sprachen" tabindex="-1">Unterstützte Sprachen <a class="header-anchor" href="#unterstutzte-sprachen" aria-label="Permalink to &quot;Unterstützte Sprachen&quot;">​</a></h2><p>Nicasa unterstützt eine Vielzahl von Sprachen, darunter Englisch, Chinesisch (vereinfacht), Chinesisch (traditionell), Japanisch, Französisch, Koreanisch, Deutsch, Spanisch, Italienisch, Vietnamesisch, Thailändisch, Hindi, Türkisch, Russisch, Portugiesisch, Niederländisch, Deutsch (Schweiz), Finnisch, Malaiisch, Griechisch, Norwegisch, Indonesisch, Ungarisch, Dänisch und Ukrainisch.</p><h2 id="erste-schritte" tabindex="-1">Erste Schritte <a class="header-anchor" href="#erste-schritte" aria-label="Permalink to &quot;Erste Schritte&quot;">​</a></h2><p>Wenn du neu bei Nicasa bist, beginne mit der <a href="/de/guide/installation.html">Installationsanleitung</a>, um die App auf deinem Mac zum Laufen zu bringen.</p>',22)])])}const f=n(t,[["render",s]]);export{g as __pageData,f as default};
